<style scoped lang="scss" src="./message.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import {
  MessageMode,
  MessageModeValues,
} from "../message/message.constants.js";
import Icon from "../../components/icon/icon.vue";
import { IconShape } from "../../components/icon/icon.constants";
import DesktopOnly from "../desktop-only/desktop-only";
import MobileOnly from "../mobile-only/mobile-only";
import { has } from "../../util/has";

/**
 * A simple notification message to help indicate an important piece of
 * information.
 */
@Component({
  components: {
    Icon,
    DesktopOnly,
    MobileOnly,
  },
})
export default class Message extends Vue {
  /** Render mode of the message */
  @Prop({
    type: String,
    default: MessageMode.ALERT,
    validator: has(MessageModeValues),
  })
  mode;

  /** Message title */
  @Prop({
    type: String,
    default: "",
  })
  title;

  /** Body of text the message will display */
  @Prop({
    type: String,
    default: "",
  })
  body;

  /** An icon shape to render with the message */
  @Prop({
    type: Number,
  })
  icon;

  /**
   * When true, an icon will display which will allow the user to dismiss the
   * message
   */
  @Prop({
    type: Boolean,
    default: undefined,
  })
  closeable;

  IconShape = IconShape;

  handleClick() {
    /**
     * Close event when the user attempts to dismiss the message
     */
    this.$emit("close");
  }

  inAlertMode() {
    return this.mode === MessageMode.ALERT;
  }

  inTipMode() {
    return this.mode === MessageMode.TIP;
  }

  get backgroundColor() {
    const colors = {
      alert: "Message--alertBgd",
      tip: "Message--tipBgd",
    };

    return colors[this.mode];
  }

  get titleStyle() {
    const colors = {
      alert: "Message--alertTitle",
      tip: "Message--tipTitle",
    };

    return colors[this.mode];
  }

  get bodyStyle() {
    const heights = {
      alert: "Message--alertBody",
      tip: "Message--tipBody",
    };

    return heights[this.mode];
  }

  get slotStyle() {
    if (this.$slots.default) {
      return {
        margin: "10px 0px 0px 0px",
        maxWidth: "206px",
        overflow: "hidden",
      };
    }

    return {};
  }
}
</script>

<template>
  <div :class="['Message', backgroundColor]">
    <div class="Message__Content">
      <div class="Message__Main">
        <div class="Message__Left">
          <div v-if="Boolean(icon)" class="Message__Icon">
            <Icon :shape="icon" :size="24" :color="'#2356F6'" />
          </div>
          <div v-if="inAlertMode()" class="Message__Fence" />
        </div>
        <div class="Message__Right">
          <div :class="['Message__Title', titleStyle]">{{ title }}</div>
          <div :class="['Message__Body', bodyStyle]" v-html="body"></div>
          <div :style="slotStyle">
            <slot />
          </div>
        </div>
      </div>
      <div v-if="closeable" class="Message__CloseButton" @click="handleClick">
        <Icon :shape="IconShape.CLOSE" :size="12" />
      </div>
    </div>
  </div>
</template>
